let risks = [];

// 1. Quantity Checks
if ($quantity_ordered !== $received_qty) {
    risks.push(`Quantity Mismatch: Ordered ${$quantity_ordered}, but Received ${$received_qty}.`);
}
if ($invoice_qty > $received_qty) {
    risks.push(`Overbilling Risk: Invoiced for ${$invoice_qty}, but only Received ${$received_qty}.`);
}

// 2. Amount Check (Allowing a 1 unit margin for minor decimal/rounding differences)
if (Math.abs($total_amount - $total_invoice_amount) > 1) {
    risks.push(`Amount Mismatch: PO Total was ${$total_amount}, but Invoice is ${$total_invoice_amount}.`);
}

// Final Evaluation (Must return a string)
if (risks.length > 0) {
    return "THREE-WAY MATCH FAILED: " + risks.join(" | ");
} else {
    return "PASS: Three-way match successful. Quantities and amounts align perfectly.";
}
